  slice: () => { noise(.12, .14, 900); tone(500 + Math.random() * 300, .1, .07, 'triangle', 0, 200); },
  gold: () => [880, 1175, 1568].forEach((f, i) => tone(f, .25, .09, 'triangle', i * .06)),
