  for (let i = 0; i < 14; i++) { const a = rand(0, 6.28), v = rand(120, 460); parts.push({ x: f.x, y: f.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 120, life: rand(.5, 1), max: 1, r: rand(2.5, 6.5), c: col }); }
  splat(f.x, f.y, col, 1);
