  for (let i = 0; i < 40; i++) { const a = rand(0, 6.28), v = rand(200, 760); parts.push({ x: f.x, y: f.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: rand(.5, 1.1), max: 1.1, r: rand(3, 9), c: pick(['#ffdd66', '#ff8a3a', '#ff4a2a', '#fff']) }); }
