    p.m.position.copy(pos); p.m.material.color.setHex(color); p.m.visible = true; p.m.scale.setScalar(rand(.7, 1.4));
    p.v.set(Math.cos(a) * s, rand(0, 1) * up + up * .3, Math.sin(a) * s); p.life = p.max = life * rand(.7, 1.1);
