  const gm = new THREE.MeshPhongMaterial({ color: 0xffd54a, emissive: 0x6b4200, shininess: 110, specular: 0xffffff }); mats.push(gm);
  const dg = new THREE.CylinderGeometry(R + .45, R + .45, .7, 56); dg.translate(0, -.35, 0);
