const POW = { E: { c: '#4ade80', t: 'Mở rộng!' }, M: { c: '#22d3ee', t: 'Nhiều bóng!' }, F: { c: '#fb923c', t: 'Bóng lửa!' }, L: { c: '#f472b6', t: 'Súng laser!' }, S: { c: '#60a5fa', t: 'Bóng chậm!' }, H: { c: '#f87171', t: '+1 mạng!' } };

