  S.lv[key] = { stars: Math.max(cur.stars, stars), best: Math.max(cur.best, G.score) }; S.unlocked = Math.max(S.unlocked, Math.min(LEVELS.length, G.i + 2)); S.best = Math.max(S.best, G.score); persist();
