    const t = clamp((b.x - G.px) / (pw / 2), -1, 1), a = t * 1.05, s = spd0(); b.vx = Math.sin(a) * s; b.vy = -Math.cos(a) * s; b.y = pY - r; G.hits = 0; hud(); sfx.paddle(); burst(b.x, pY, '#7df9ff', 4, 120);
