  Object.keys(G.fx).forEach(k => { if (G.fx[k] > 0) { G.fx[k] -= dt; if (k === 'S' && G.fx[k] <= 0) G.balls.forEach(b => { if (!b.stuck) { const s = Math.hypot(b.vx, b.vy) || 1, n = spd0(); b.vx *= n / s; b.vy *= n / s; } }); } });
