    if (tg) { dmgMonster(tg, b.dmg, { slow: b.slow, slowT: b.slowT }); part(px(b.u), py(b.row + .5), 5, b.style === 'ice' ? ['#bfe6ff', '#fff'] : ['#b6f26f', '#fff'], 80, 30, .3, 2.5); sfx.hit(); if (b.pierce > 0) { b.pierce--; (b.hits = b.hits || []).push(tg.uid); } else G.bullets.splice(i, 1); }
