      ctx.fillStyle = 'rgba(0,0,0,.55)'; ctx.fillRect(bx - 1, by - 1, bw + 2, 7); ctx.fillStyle = m.hp / m.maxHp > .4 ? '#8fdc63' : '#ff6a4a'; ctx.fillRect(bx, by, bw * clamp(m.hp / m.maxHp, 0, 1), 5);
