const raw = k => { try { return localStorage.getItem(k); } catch (e) { return null; } };
const n = v => (v || 0).toLocaleString('vi-VN');
const sumStars = o => Object.values((o && o.lv) || {}).reduce((a, b) => a + (b.stars || 0), 0);

